  async function orders() { heading(tr('الطلبات', 'Orders'), tr('التجهيز والإسناد والتحصيل حالات منفصلة في سجل الطلب نفسه.', 'Preparation, assignment and collection remain separate states on one order record.'), `<button class="quiet" data-action="refresh">${esc(tr('تحديث', 'Refresh'))}</button>`); await loadBranches(); const d = await api(`/api/orders?${queryFilters()}`); state.orders = (d.orders || []).map(normalizeOrder); $('#content').innerHTML = `<div class="stack">${filterForm()}${['owner','branch_manager'].includes(state.user.role)?`<div class="actions"><button class="quiet" data-action="branch-availability">${esc(tr('إدارة توفر الأصناف بالفرع','Branch item availability'))}</button></div>`:''}${state.orders.length ? `<div class="grid">${state.orders.map(orderCard).join('')}</div>` : empty(tr('لا توجد طلبات ضمن الفلاتر المحددة.', 'No orders match these filters.'))}${d.next_offset != null ? `<button class="quiet" data-action="more-orders" data-offset="${esc(d.next_offset)}">${esc(tr('تحميل المزيد', 'Load more'))}</button>` : ''}</div>`; }
