  function shiftCard(s) { const close = s.submission || s.closure || {}; const own = s.user_id === state.user.id || s.driver_id === state.user.id; return `<article class="panel"><div class="card-head"><div><h3>${esc(s.display_name || s.user_name || s.name || (s.kind === 'manager' ? tr('مدير التوصيل', 'Delivery manager') : tr('سائق', 'Driver')))}</h3><p class="code">${esc(s.id)}</p></div>${badge(s.status)}</div><p class="small-text muted">${esc(s.kind === 'manager' ? tr('شفت مدير', 'Manager shift') : tr('شفت سائق', 'Driver shift'))} · ${esc(datetime(s.opened_at || s.created_at))}</p><dl class="data-grid">${dataItem(tr('المتوقع', 'Expected'), (s.expected_halalas??close.expected_halalas)==null?'—':money(s.expected_halalas??close.expected_halalas))}${dataItem(tr('المعدود', 'Counted'), close.counted_halalas == null ? '—' : money(close.counted_halalas))}${dataItem(tr('المستلم المؤكد', 'Confirmed received'), (s.received_halalas??close.received_halalas)==null?'—':money(s.received_halalas??close.received_halalas))}${dataItem(tr('الفرق', 'Difference'), close.difference_halalas == null ? '—' : money(close.difference_halalas), 'difference')}</dl><div class="actions"><button class="quiet" data-action="shift-detail" data-id="${esc(s.id)}">${esc(tr('تفاصيل ومراجعة التقفيلة', 'Shift details & closure review'))}</button>${s.kind==='manager'&&(own||isAdmin())&&['open','closing'].includes(s.status)?`<button class="quiet" data-action="handover-manager" data-id="${esc(s.id)}">${esc(tr('تسليم المناوبة بقبول المستلم','Hand over shift with recipient acceptance'))}</button>`:''}${(own || isAdmin()) && s.status === 'open' ? `<button data-action="start-closing" data-id="${esc(s.id)}">${esc(tr('بدء التقفيلة', 'Start closure'))}</button>` : ''}</div></article>`; }
